     1→<!-- Signal Chain Group Detail Fragment -->
     2→<div
     3→  data-testid="group-detail-page"
     4→  class="space-y-6"
     5→  x-data="{
     6→    showDeleteConfirmation: false,
     7→    deleting: false,
     8→    generating: false,
     9→    openDeleteModal() {
    10→      this.showDeleteConfirmation = true;
    11→    },
    12→    closeDeleteModal() {
    13→      this.showDeleteConfirmation = false;
    14→    },
    15→    performDelete() {
    16→      this.deleting = true;
    17→      fetch('/api/signal-chain-groups/{{ group.id }}', { method: 'DELETE' })
    18→        .then(response => {
    19→          if (response.ok) {
    20→            window.location.href = '/library/groups';
    21→          } else {
    22→            alert('Failed to delete group');
    23→            this.deleting = false;
    24→            this.showDeleteConfirmation = false;
    25→          }
    26→        })
    27→        .catch(() => {
    28→          alert('Failed to delete group');
    29→          this.deleting = false;
    30→          this.showDeleteConfirmation = false;
    31→        });
    32→    },
    33→    generateChains() {
    34→      this.generating = true;
    35→      fetch('/api/signal-chain-groups/{{ group.id }}/generate', {
    36→        method: 'POST',
    37→        headers: {
    38→          'Content-Type': 'application/json'
    39→        }
    40→      })
    41→        .then(response => {
    42→          if (response.ok) {
    43→            window.location.href = '/library/chains';
    44→          } else {
    45→            alert('Failed to generate chains');
    46→            this.generating = false;
    47→          }
    48→        })
    49→        .catch(() => {
    50→          alert('Failed to generate chains');
    51→          this.generating = false;
    52→        });
    53→    }
    54→  }"
    55→>
    56→  <!-- Group Info -->
    57→  <div class="bg-card border border-border rounded-lg p-6">
    58→    <h2 class="text-xl font-bold text-[var(--color-text-primary)] mb-2">
    59→      {{ group.name }}
    60→    </h2>

